void PlaybackTtsStreamAsyncWaiter::Play(
    ::mojo::PendingReceiver<TtsEventObserver>* out_event_observer) {
  base::RunLoop loop;
  proxy_->Play(
      base::BindOnce(
          [](base::RunLoop* loop,
             ::mojo::PendingReceiver<TtsEventObserver>* out_event_observer
,
             ::mojo::PendingReceiver<TtsEventObserver> event_observer) {*out_event_observer = std::move(event_observer);
            loop->Quit();
          },
          &loop,
          out_event_observer));
  loop.Run();
}

::mojo::PendingReceiver<TtsEventObserver> PlaybackTtsStreamAsyncWaiter::Play(
    ) {
  ::mojo::PendingReceiver<TtsEventObserver> async_wait_result;
  Play(&async_wait_result);
  return async_wait_result;
}




